  /** helper function to set the values of all input ports.
   * @param chargerState payload for data port chargerState
   * @param batteryQualification payload for data port batteryQualification
   * @param flightQualification payload for data port flightQualification
   * @param currentLifecycleState payload for data port currentLifecycleState
   */
  def put_concrete_inputs(chargerState : Drone_Lifecycle_Governor.ChargerState.Type,
                          batteryQualification : Drone_Lifecycle_Governor.BatteryQualification.Type,
                          flightQualification : Drone_Lifecycle_Governor.FlightQualification.Type,
                          currentLifecycleState : Drone_Lifecycle_Governor.LifecycleState.Type): Unit = {
    put_chargerState(chargerState)
    put_batteryQualification(batteryQualification)
    put_flightQualification(flightQualification)
    put_currentLifecycleState(currentLifecycleState)
  }


  /** helper function to check OperationalEligibilityOwner_governorProcess_operationalEligibilityOwner's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param recoveryProposal method that will be called with the value of the outgoing data
   *        port 'recoveryProposal'.
   * @param eligibilityEnvelope method that will be called with the value of the outgoing data
   *        port 'eligibilityEnvelope'.
   */
  def check_concrete_output(recoveryProposal: Drone_Lifecycle_Governor.RecoveryProposal.Type => B,
                            eligibilityEnvelope: Drone_Lifecycle_Governor.EligibilityEnvelope => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val recoveryProposalValue: Drone_Lifecycle_Governor.RecoveryProposal.Type = get_recoveryProposal().get
    if(!recoveryProposal(recoveryProposalValue)) {
      testFailures = testFailures :+ st"'recoveryProposal' did not match expected: value of the outgoing data port is ${recoveryProposalValue}"
    }
    val eligibilityEnvelopeValue: Drone_Lifecycle_Governor.EligibilityEnvelope = get_eligibilityEnvelope().get
    if(!eligibilityEnvelope(eligibilityEnvelopeValue)) {
      testFailures = testFailures :+ st"'eligibilityEnvelope' did not match expected: value of the outgoing data port is ${eligibilityEnvelopeValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


